// ============================================================
// PTS3 Result - Client Script (Visual Inspection)
// Renders: Summary, Step Sweep, Mode, Left/Right/Diff, Artifacts
// Uses final_graph_json, mode_values_json, left_right_diff_summary_json, artifact_paths
// ============================================================

(function () {
  if (document.getElementById("pts3-result-style") == null) {
    var style = document.createElement("style");
    style.id = "pts3-result-style";
    style.textContent = ".pts3-result-section{margin:1rem 0;padding:0.75rem;border:1px solid #d1d8dd;border-radius:4px;}.pts3-result-section h4{margin:0 0 0.5rem 0;font-size:1rem;color:#36414c;}.pts3-result-table{font-size:0.85em;border-collapse:collapse;}.pts3-result-table th,.pts3-result-table td{border:1px solid #d1d8dd;padding:4px 8px;text-align:left;}.pts3-result-table th{background:#f5f7fa;}.pts3-result-artifact{margin:0.25rem 0;font-size:0.9em;}.pts3-result-no-data{color:#8d99a6;font-style:italic;}.pts3-result-pass{color:#27ae60;}.pts3-result-fail{color:#e74c3c;}";
    document.head.appendChild(style);
  }

  function safe_json(str, fallback) {
    if (!str || typeof str !== "string") return fallback || {};
    try {
      var o = JSON.parse(str);
      return o && typeof o === "object" ? o : (fallback || {});
    } catch (e) {
      return fallback || {};
    }
  }

  function escape_html(s) {
    if (s == null || s === undefined) return "";
    var t = String(s);
    return t.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }

  function render_summary(frm) {
    var d = frm.doc;
    var html = '<div class="pts3-result-section"><h4>Summary</h4><table class="pts3-result-table"><tbody>';
    html += "<tr><th>PCB Serial No</th><td>" + escape_html(d.pcb_serial_no || "") + "</td></tr>";
    html += "<tr><th>Run ID</th><td>" + escape_html(d.run_id || "") + "</td></tr>";
    html += "<tr><th>Operation</th><td>" + escape_html(d.operation || "") + "</td></tr>";
    html += "<tr><th>Datetime</th><td>" + escape_html(d.datetime || "") + "</td></tr>";
    var pf = (d.pass_fail || "").trim();
    var pfClass = pf === "Pass" ? "pts3-result-pass" : pf === "Fail" ? "pts3-result-fail" : "";
    html += "<tr><th>Pass/Fail</th><td class=\"" + pfClass + "\">" + escape_html(pf || "-") + "</td></tr>";
    html += "<tr><th>Dominant Channel</th><td>" + escape_html(d.dominant_channel || "") + "</td></tr>";
    html += "<tr><th>Max Value</th><td>" + escape_html(d.max_value != null ? d.max_value : "") + "</td></tr>";
    html += "</tbody></table></div>";
    return html;
  }

  function render_step_sweep(frm) {
    var g = safe_json(frm.doc.final_graph_json, null);
    if (!g || g.type !== "sweep") {
      return '<div class="pts3-result-section"><h4>Step Sweep</h4><p class="pts3-result-no-data">No sweep data</p></div>';
    }
    var freqs = g.freqs || [];
    var left = g.left || [];
    var right = g.right || [];
    var diff = g.diff || [];
    var html = '<div class="pts3-result-section"><h4>Step Sweep</h4><table class="pts3-result-table"><thead><tr><th>Freq (Hz)</th><th>Left</th><th>Right</th><th>Diff</th></tr></thead><tbody>';
    for (var i = 0; i < freqs.length; i++) {
      html += "<tr><td>" + escape_html(freqs[i]) + "</td><td>" + escape_html(left[i] != null ? left[i] : "") + "</td><td>" + escape_html(right[i] != null ? right[i] : "") + "</td><td>" + escape_html(diff[i] != null ? diff[i] : "") + "</td></tr>";
    }
    html += "</tbody></table></div>";
    return html;
  }

  function get_mode_value(m, key) {
    if (m[key]) return m[key];
    var lower = key.toLowerCase();
    if (m[lower]) return m[lower];
    return null;
  }

  function render_mode(frm) {
    var m = safe_json(frm.doc.mode_values_json, null);
    if (!m || typeof m !== "object") {
      return '<div class="pts3-result-section"><h4>Mode Results</h4><p class="pts3-result-no-data">No mode data</p></div>';
    }
    var order = ["Mode1", "Mode2", "Mode3", "Mode0"];
    var html = '<div class="pts3-result-section"><h4>Mode Results</h4><table class="pts3-result-table"><thead><tr><th>Mode</th><th>P1</th><th>P2</th><th>Diff</th></tr></thead><tbody>';
    for (var i = 0; i < order.length; i++) {
      var k = order[i];
      var v = get_mode_value(m, k);
      if (v && typeof v === "object") {
        html += "<tr><td>" + escape_html(k) + "</td><td>" + escape_html(v.p1 != null ? v.p1 : "") + "</td><td>" + escape_html(v.p2 != null ? v.p2 : "") + "</td><td>" + escape_html(v.diff != null ? v.diff : "") + "</td></tr>";
      }
    }
    html += "</tbody></table></div>";
    return html;
  }

  function render_lrd_summary(frm) {
    var t = safe_json(frm.doc.left_right_diff_summary_json, null);
    if (!t || typeof t !== "object") {
      return '<div class="pts3-result-section"><h4>Left / Right / Diff Summary</h4><p class="pts3-result-no-data">No data</p></div>';
    }
    var meta = t.metadata || {};
    var left = t.left || {};
    var right = t.right || {};
    var diff = t.diff || {};
    var keys = Object.keys(left).concat(Object.keys(right)).concat(Object.keys(diff));
    keys = keys.filter(function (k, i, a) { return a.indexOf(k) === i; }).sort();
    var html = '<div class="pts3-result-section"><h4>Left / Right / Diff Summary</h4>';
    if (Object.keys(meta).length) {
      html += "<p><strong>Metadata:</strong> " + escape_html(JSON.stringify(meta)) + "</p>";
    }
    html += "<table class=\"pts3-result-table\"><thead><tr><th>Key</th><th>Left</th><th>Right</th><th>Diff</th></tr></thead><tbody>";
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      html += "<tr><td>" + escape_html(k) + "</td><td>" + escape_html(left[k] != null ? left[k] : "") + "</td><td>" + escape_html(right[k] != null ? right[k] : "") + "</td><td>" + escape_html(diff[k] != null ? diff[k] : "") + "</td></tr>";
    }
    html += "</tbody></table></div>";
    return html;
  }

  function render_artifacts(frm) {
    var ap = frm.doc.artifact_paths || "";
    var html = '<div class="pts3-result-section"><h4>Artifacts</h4>';
    var obj = null;
    if (typeof ap === "string" && ap.trim()) {
      try {
        obj = JSON.parse(ap);
      } catch (e) {
        obj = null;
      }
    }
    if (obj && typeof obj === "object") {
      var pc = obj.pc_name || "";
      var excel = obj.excel_path || "";
      var log = obj.log_path || "";
      var plot = obj.plot_path || "";
      html += "<div class=\"pts3-result-artifact\"><strong>PC:</strong> " + escape_html(pc || "(not set)") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Excel:</strong> " + escape_html(excel || "-") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Log:</strong> " + escape_html(log || "-") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Plot:</strong> " + escape_html(plot || "-") + "</div>";
    } else if (ap && typeof ap === "string") {
      html += "<div class=\"pts3-result-artifact\"><strong>Legacy path:</strong> " + escape_html(ap) + "</div>";
    } else {
      html += "<p class=\"pts3-result-no-data\">No artifact paths</p>";
    }
    html += "</div>";
    return html;
  }

  function render_inspection(frm) {
    if (!frm.doc.name) return "";
    var html = render_summary(frm) + render_step_sweep(frm) + render_mode(frm) + render_lrd_summary(frm) + render_artifacts(frm);
    return html;
  }

  frappe.ui.form.on("PTS3 Result", {
    refresh: function (frm) {
      var field = frm.get_field("result_inspection");
      if (field && field.$wrapper) {
        field.$wrapper.html(render_inspection(frm));
      }
    }
  });
})();

#!/usr/bin/env python3
"""
Upsert Client Script:
  Name: PCB Ledger - Visual Timeline Display
  DocType: PCB Ledger

Renders the PCB ledger visual timeline into the HTML field `visual_timeline_html`,
which is already placed in the right column of the Lifecycle Tracking section.
"""

import os
import sys

sys.path.insert(0, os.getcwd())
from AUTO_EXECUTE_FRAPPE_CONSOLE import execute_frappe_command


SCRIPT_JS = """
frappe.ui.form.on('PCB Ledger', {
    refresh(frm) {
        // Use the new dark visual timeline renderer
        render_pcb_visual_timeline_v2(frm);
    },
    after_save(frm) {
        render_pcb_visual_timeline_v2(frm);
    },
});

function render_pcb_visual_timeline(frm) {
    if (!frm || !frm.doc) return;

    const field = frm.fields_dict && frm.fields_dict['visual_timeline_html'];
    if (!field || !field.$wrapper) {
        console.warn('[PCB Timeline] visual_timeline_html field not found');
        return;
    }

    const wrapper = field.$wrapper;
    wrapper.empty();

    const rows = (frm.doc.pcb_ledger_timeline || []).slice();
    if (!rows.length) {
        wrapper.append('<div class=\"text-muted small\">No PCB history yet.</div>');
        return;
    }

    // Sort by event_time ascending (string compare is fine for ISO datetime)
    rows.sort(function (a, b) {
        const ta = a.event_time || '';
        const tb = b.event_time || '';
        if (ta < tb) return -1;
        if (ta > tb) return 1;
        return 0;
    });

    const card = $('<div class=\"pcb-visual-timeline-card\"></div>').appendTo(wrapper);
    $('<div class=\"pcb-visual-timeline-header\">PCB History Timeline</div>').appendTo(card);

    const list = $('<div class=\"pcb-visual-timeline-list\"></div>').appendTo(card);

    rows.forEach(function (row) {
        const rawEventType = row.event_type || '';
        const eventType = frappe.utils.escape_html(rawEventType);
        var dateStr = '';
        try {
            if (row.event_time) {
                dateStr = frappe.datetime.str_to_user(row.event_time);
            }
        } catch (e) {
            dateStr = row.event_time || '';
        }

        const fromLoc = row.from_location || '';
        const toLoc = row.to_location || '';
        let movement = '';
        if (fromLoc || toLoc) {
            movement = fromLoc || '';
            if (toLoc) {
                movement += (movement ? ' \u2192 ' : '') + toLoc; // arrow
            }
        }

        let ref = '';
        if (row.ref_doctype && row.ref_docname) {
            ref = frappe.utils.escape_html(row.ref_doctype + ' - ' + row.ref_docname);
        }

        const rawRemarks = row.remarks || '';
        const remarks = rawRemarks ? frappe.utils.escape_html(rawRemarks) : '';

        // For PTS test events, extract status (Pass/Fail/Pending) and show as a colored chip
        let statusChipHtml = '';
        if (rawEventType === 'PTS1_UPDATED' || rawEventType === 'PTS2_UPDATED' || rawEventType === 'PTS3_UPDATED') {
            let status = null;
            // Remarks look like "PTS1 Result (Attempt N): Fail @ ..."
            const m = /Result[^:]*:\s*([A-Za-z]+)/.exec(rawRemarks || '');
            if (m && m[1]) {
                status = m[1];
            }
            if (status) {
                let cssClass = 'pcb-status-pending';
                const up = String(status).toUpperCase();
                if (up === 'PASS') cssClass = 'pcb-status-pass';
                else if (up === 'FAIL') cssClass = 'pcb-status-fail';
                statusChipHtml =
                    '<span class=\"pcb-status-chip ' +
                    cssClass +
                    '\">' +
                    frappe.utils.escape_html(status) +
                    '</span>';
            }
        } else if (rawEventType === 'MOVED_TO_REJECTED') {
            // Special "RE" chip for any movement to rejected warehouse
            statusChipHtml =
                '<span class=\"pcb-status-chip pcb-status-fail\">RE</span>';
        }

        const metaParts = [];
        if (dateStr) metaParts.push(dateStr);
        if (movement) metaParts.push(movement);
        const metaText = metaParts.join(' \u00b7 ');

        // Build remarks HTML: make PTSx result remarks more prominent, but keep
        // the original muted colour style.
        let remarksHtml = '';
        if (remarks) {
            // Base style uses the same small + text-muted classes as before.
            let remarksClass = 'pcb-visual-timeline-remarks small text-muted';
            if (rawEventType === 'PTS1_UPDATED' || rawEventType === 'PTS2_UPDATED' || rawEventType === 'PTS3_UPDATED') {
                // For PTS events, add an extra class that only increases weight/size,
                // colour still comes from text-muted.
                remarksClass += ' pcb-pts-remarks';
            }
            remarksHtml =
                '    <div class=\"' +
                remarksClass +
                '\">' +
                remarks +
                '</div>';
        }

        const itemHtml =
            '<div class=\"pcb-visual-timeline-item\">' +
            '  <div class=\"pcb-visual-timeline-marker\"></div>' +
            '  <div class=\"pcb-visual-timeline-body\">' +
            '    <div class=\"pcb-visual-timeline-title\">' +
                 eventType +
                (statusChipHtml ? ' ' + statusChipHtml : '') +
            '</div>' +
            (metaText
                ? '    <div class=\"pcb-visual-timeline-meta small text-muted\">' +
                  frappe.utils.escape_html(metaText) +
                  '</div>'
                : '') +
            (ref
                ? '    <div class=\"pcb-visual-timeline-ref small\">' + ref + '</div>'
                : '') +
            remarksHtml +
            '  </div>' +
            '</div>';

        list.append($(itemHtml));
    });

    // Inject CSS once
    if (!window.__pcb_visual_timeline_css) {
        window.__pcb_visual_timeline_css = true;
        const css =
            '<style>' +
            '.pcb-visual-timeline-card { background: #fff; border-radius: 6px; padding: 12px 16px; border: 1px solid #d1d8dd; }' +
            '.pcb-visual-timeline-header { font-weight: 600; margin-bottom: 8px; }' +
            '.pcb-visual-timeline-list { position: relative; margin-left: 4px; }' +
            '.pcb-visual-timeline-item { display: flex; margin-bottom: 10px; position: relative; }' +
            '.pcb-visual-timeline-marker { width: 10px; margin-right: 8px; position: relative; }' +
            '.pcb-visual-timeline-marker::before { content: \"\"; position: absolute; left: 3px; top: 3px; width: 6px; height: 6px; border-radius: 50%; background: #5e64ff; }' +
            '.pcb-visual-timeline-marker::after { content: \"\"; position: absolute; left: 6px; top: 10px; width: 2px; bottom: -10px; background: #d1d8dd; }' +
            '.pcb-visual-timeline-item:last-child .pcb-visual-timeline-marker::after { display: none; }' +
            '.pcb-visual-timeline-body { flex: 1; }' +
            '.pcb-visual-timeline-title { font-weight: 500; display: flex; align-items: center; gap: 6px; }' +
            '.pcb-visual-timeline-ref { margin-top: 2px; }' +
            '.pcb-visual-timeline-remarks { margin-top: 2px; }' +
            '.pcb-pts-remarks { margin-top: 4px; font-weight: 600; }' +
            '.pcb-status-chip { display: inline-block; padding: 1px 6px; border-radius: 999px; font-size: 10px; }' +
            '.pcb-status-pass { background: #d4edda; color: #155724; }' +
            '.pcb-status-fail { background: #f8d7da; color: #721c24; }' +
            '.pcb-status-pending { background: #fff3cd; color: #856404; }' +
            '</style>';
        $(document.head).append(css);
    }
}

// New dark visual timeline card (based on HTML visualization plan)
function render_pcb_visual_timeline_v2(frm) {
