        console.warn('[PCB Timeline] visual_timeline_html field not found');
        return;
    }

    const wrapper = field.$wrapper;
    wrapper.empty();

    const rows = (frm.doc.pcb_ledger_timeline || []).slice();
    if (!rows.length) {
        wrapper.append('<div class="text-muted small">No PCB history yet.</div>');
        return;
    }

    const cardId = `pcb-timeline-card-${frm.doc.name || 'new'}`;
    const listId = `pcb-timeline-list-${frm.doc.name || 'new'}`;
    const pillId = `pcb-timeline-pill-${frm.doc.name || 'new'}`;

    const cardHtml = `
        <div class="pcb-card" id="${cardId}">
            <div class="pcb-head">
                <div>
                    <div class="pcb-title">PCB History Timeline</div>
                    <div class="pcb-sub">Latest movement and reference docs for this PCB</div>
                </div>
                <div class="pcb-pill" id="${pillId}">Events: 0</div>
            </div>
            <div class="pcb-body">
                <div class="pcb-list" id="${listId}"></div>
            </div>
        </div>
    `;
    wrapper.append(cardHtml);

    // Inject CSS once for the dark visual timeline
    if (!window.__pcb_timeline_toggle_css) {
        window.__pcb_timeline_toggle_css = true;
        const css = `
