#!/usr/bin/env python3
"""
PTS3 Station Connector

Polls ERP for PTS3 Test jobs with Requested lanes for this target_pc, claims lanes,
runs AUTO_PTS3v17.py --cli (or the local pts3_runner_daemon), streams live events to ERP.

Oscilloscope: On startup, connects to pts3_runner_daemon (127.0.0.1:8765) and sends cmd=init
so VISA scope is open before operators press Step sweep / Mode. Jobs then use the same
runner process (no cold PyVISA + full script import per button press).

Env:
  PTS3_AUTO_START_RUNNER=1 — spawn pts3_runner_daemon.py if the port is closed
  PTS3_RUNNER_HOST / PTS3_RUNNER_PORT — runner address (default 127.0.0.1:8765)

v1: Single-lane operator mode — processes only lane_no == 1. Lanes 2, 3, 4 are ignored.

Sources: pts3_api_server_script.py, 21_PTS3_API_DEPLOYMENT_AND_TESTS.md,
        22_PTS3_API_HARDENING_REPORT.md, 09_CLI_SPEC.md, 12_LIVE_UPDATE_FLOW.md
"""

import os
import sys
import time
import json
import socket
import subprocess
import threading

import requests

# -----------------------------------------------------------------------------
# Config (env or defaults)
# -----------------------------------------------------------------------------
ERP_URL = os.environ.get("PTS3_ERP_URL", "http://192.168.1.50:8080/")  # MUST end with /
API_KEY = os.environ.get("PTS3_API_KEY", "95403196454d1c9")
API_SECRET = os.environ.get("PTS3_API_SECRET", "eac4a78c7ddafa8")

# Path to AUTO_PTS3v16.py (real worker). Must run from script directory.
BASE_DIR = os.path.dirname(os.path.abspath(__file__))
PTS3_SCRIPT = os.environ.get("PTS3_SCRIPT_PATH", os.path.join(BASE_DIR, "AUTO_PTS3v17.py"))
PYTHON_PATH = os.environ.get("PTS3_PYTHON_PATH", sys.executable)

# Optional persistent local runner (keeps scope open across actions)
PTS3_RUNNER_HOST = os.environ.get("PTS3_RUNNER_HOST", "127.0.0.1")
PTS3_RUNNER_PORT = int(os.environ.get("PTS3_RUNNER_PORT", "8765"))
RUNNER_SCRIPT = os.path.join(BASE_DIR, "pts3_runner_daemon.py")


def runner_port_open():
    try:
        s = socket.create_connection((PTS3_RUNNER_HOST, PTS3_RUNNER_PORT), timeout=0.4)
        s.close()
        return True
    except Exception:
        return False


def start_runner_daemon_if_configured():
    """
    Auto-start the local runner daemon (recommended).

    Default: ON (so running the connector is enough).
    Disable by setting: PTS3_DISABLE_AUTO_START_RUNNER=1
    """
    disable = (os.environ.get("PTS3_DISABLE_AUTO_START_RUNNER") or "").strip().lower()
    if disable in ("1", "true", "yes", "on"):
        return False
    if runner_port_open():
        return True
    if not os.path.isfile(RUNNER_SCRIPT):
        print("[PTS3] Runner file missing: %s" % RUNNER_SCRIPT)
        return False
    try:
        popen_kw = {"cwd": BASE_DIR}
        if sys.platform == "win32":
            cf = getattr(subprocess, "CREATE_NO_WINDOW", 0)
            if cf:
                popen_kw["creationflags"] = cf
        # Capture logs so we can debug daemon startup failures.
        try:
            log_path = os.path.join(BASE_DIR, "runner_daemon.log")
            lf = open(log_path, "a", encoding="utf-8", errors="replace")
            popen_kw["stdout"] = lf
            popen_kw["stderr"] = lf
            print("[PTS3] Starting runner daemon, logs -> %s" % log_path)
        except Exception:
            lf = None
        subprocess.Popen([PYTHON_PATH, "-u", RUNNER_SCRIPT], **popen_kw)
        for _ in range(50):
            time.sleep(0.15)
            if runner_port_open():
                print("[PTS3] Started pts3_runner_daemon on %s:%s" % (PTS3_RUNNER_HOST, PTS3_RUNNER_PORT))
                return True
        print("[PTS3] Runner was started but port %s is not open yet (retrying warmup)" % PTS3_RUNNER_PORT)
        return runner_port_open()
    except Exception as e:
        print("[PTS3] Could not start runner daemon: %s" % e)
        return False


def warm_runner_scope():
    """
    Ask the local runner to open the VISA scope once so step_sweep/mode only play audio + read.
    Call this at connector startup (after optional auto-start).
    """
    if not runner_port_open():
        return False
    s = None
    try:
        s = socket.create_connection((PTS3_RUNNER_HOST, PTS3_RUNNER_PORT), timeout=8.0)
    except Exception as e:
        print("[PTS3] Scope warmup: cannot connect to runner: %s" % e)
        return False
    try:
        s.sendall((json.dumps({"cmd": "init"}) + "\n").encode("utf-8", errors="replace"))
        f = s.makefile("r", encoding="utf-8", errors="replace", newline="\n")
        deadline = time.time() + 90.0
        while time.time() < deadline:
            line = f.readline()
            if not line:
                break
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                continue
            if obj.get("type") == "init_complete" and obj.get("ok"):
                print("[PTS3] Oscilloscope pre-initialized (runner): %s" % (obj.get("resource") or ""))
                return True
        print("[PTS3] Scope warmup: no init_complete from runner (timeout)")
        return False
    finally:
        try:
            if s is not None:
                s.close()
        except Exception:
            pass


def prepare_scope_for_station():
    """Start runner if configured; pre-open VISA so UI actions are fast."""
    start_runner_daemon_if_configured()
    for attempt in range(4):
        if warm_runner_scope():
            return True
        if attempt < 3:
            time.sleep(0.6)
    print("[PTS3] Runner not warmed — each ERP job may spawn a new Python process (full VISA init).")
    print("[PTS3] For hot scope: keep pts3_runner_daemon.py running, or set PTS3_AUTO_START_RUNNER=1")
    return False


def open_runner_stream(cli_mode, serial, lane_no, run_id):
    # Important: connect with a short timeout, then disable timeout for long streaming.
    # Otherwise reads can raise "timed out" mid-test if no line arrives in time.
    s = socket.create_connection((PTS3_RUNNER_HOST, PTS3_RUNNER_PORT), timeout=2.0)
    try:
        s.settimeout(None)
    except Exception:
        pass
    f = s.makefile("r", encoding="utf-8", errors="replace", newline="\n")
    payload = {
        "cmd": cli_mode,
        "operation": cli_mode,
        "serial": serial,
        "lane_no": int(lane_no),
        "run_id": run_id
    }
    s.sendall((json.dumps(payload) + "\n").encode("utf-8", errors="replace"))
    # Return iterator over lines; keep socket alive by attaching it
    f._pts3_sock = s  # type: ignore[attr-defined]
    return f


def request_runner_abort(run_id, serial, lane_no):
    try:
        s = socket.create_connection((PTS3_RUNNER_HOST, PTS3_RUNNER_PORT), timeout=2.0)
        s.sendall((json.dumps({"cmd": "abort", "run_id": run_id, "serial": serial, "lane_no": int(lane_no)}) + "\n").encode("utf-8", errors="replace"))
        try:
            s.close()
        except Exception:
            pass
    except Exception:
        pass

# Polling
POLL_SEC = 2.0
HEARTBEAT_SEC = 5.0
ABORT_CHECK_SEC = 0.5

# Station identity
TARGET_PC = os.environ.get("PTS3_TARGET_PC", socket.gethostname())
CONNECTOR_NAME = TARGET_PC

HEADERS = {"Content-Type": "application/json"}
if API_KEY and API_SECRET:
    HEADERS["Authorization"] = "token %s:%s" % (API_KEY, API_SECRET)


def urljoin(path):
    return (ERP_URL.rstrip("/") + "/" + path.lstrip("/"))


# -----------------------------------------------------------------------------
# ERP API
# -----------------------------------------------------------------------------

def call_pts3_api(args, timeout=20):
    """POST to pts3_api. Raises on non-200."""
    r = requests.post(
        urljoin("api/method/pts3_api"),
        headers=HEADERS,
        json=args,
        timeout=timeout
    )
    if r.status_code != 200:
        raise RuntimeError("pts3_api HTTP %s %s" % (r.status_code, (r.text or "")[:300]))
    return r


def call_pts3_api_json(args, timeout=20):
    """Call API and return parsed message dict."""
    r = call_pts3_api(args, timeout=timeout)
    try:
        data = r.json()
        return data.get("message") if isinstance(data.get("message"), dict) else {}
    except Exception:
        return {}


def api_claim_lane(docname, lane_no):
    """Claim lane. Returns {ok, run_id} or {ok: False, reason}."""
    return call_pts3_api_json({
        "api_cmd": "claim_lane",
        "docname": docname,
        "lane_no": lane_no,
        "connector_name": CONNECTOR_NAME
    }, timeout=20)


def api_update_lane_fields(docname, lane_no, run_id, fields):
    call_pts3_api({
        "api_cmd": "update_lane_fields",
        "docname": docname,
        "lane_no": lane_no,
        "run_id": run_id,
        "fields": fields
    }, timeout=20)


def api_append_lane_log(docname, lane_no, run_id, log_chunk):
    call_pts3_api({
        "api_cmd": "append_lane_log",
        "docname": docname,
        "lane_no": lane_no,
        "run_id": run_id,
        "log_chunk": log_chunk
    }, timeout=20)


def api_save_final_result(docname, lane_no, run_id, result):
    """POST save_final_result; raises if ERP returns ok=False (HTTP may still be 200)."""
    # result_json: Frappe sometimes drops nested keys on result; server merges from this string.
    try:
        result_json = json.dumps(result, default=str)
    except Exception:
        result_json = "{}"
    msg = call_pts3_api_json({
        "api_cmd": "save_final_result",
        "docname": docname,
        "lane_no": lane_no,
        "run_id": run_id,
        "result": result,
        "result_json": result_json,
    }, timeout=120)
    if not msg.get("ok"):
        reason = msg.get("reason") or msg.get("message") or repr(msg)
        raise RuntimeError("save_final_result rejected: %s" % reason)


def api_mark_lane_failed(docname, lane_no, run_id, error_message):
    call_pts3_api({
        "api_cmd": "mark_lane_failed",
        "docname": docname,
        "lane_no": lane_no,
        "run_id": run_id,
        "error_message": error_message
    }, timeout=20)


def api_abort_lane(docname, lane_no):
    call_pts3_api({
        "api_cmd": "abort_lane",
        "docname": docname,
        "lane_no": lane_no
    }, timeout=20)


def api_get_status_snapshot(docname):
    """Get doc + lanes for UI. Returns {ok, doc, lanes}."""
    return call_pts3_api_json({"api_cmd": "get_status_snapshot", "docname": docname}, timeout=10)


def abort_requested(docname, lane_no):
    """Poll ERP for abort_requested flag on lane."""
    try:
        resp = api_get_status_snapshot(docname)
        lanes = resp.get("lanes") or []
        for L in lanes:
            if int(L.get("lane_no") or 0) == lane_no:
                return bool(L.get("abort_requested"))
        return False
    except Exception:
        return False


# -----------------------------------------------------------------------------
# Polling: discover Requested lanes for this target_pc
#
# No dedicated "list requested jobs" endpoint exists. Practical method:
# 1. Use Frappe resource API to list PTS3 Test docs where target_pc matches
# 2. For each doc, call get_status_snapshot to get lane details
# 3. Extract lanes with lane_action_status == "Requested"
# -----------------------------------------------------------------------------

def list_pts3_docnames_for_pc():
    """List PTS3 Test doc names where target_pc matches this machine."""
    try:
        r = requests.get(
            urljoin("api/resource/PTS3 Test"),
            params={
                "filters": json.dumps([["target_pc", "=", TARGET_PC]]),
                "fields": json.dumps(["name"]),
                "limit_page_length": 100
            },
            headers=HEADERS,
            timeout=10
        )
        if r.status_code != 200:
            return []
        data = r.json()
        rows = data.get("data") or []
        return [row.get("name") for row in rows if row.get("name")]
    except Exception:
        return []


def discover_requested_lanes():
    """
    Return list of (docname, lane_no, pcb_serial_no, lane_action) for lanes
    with status Requested, in docs matching target_pc.

    v1: Single-lane mode — only lane_no == 1 is accepted. Lanes 2, 3, 4 are ignored.
    """
    result = []
    docnames = list_pts3_docnames_for_pc()
    for docname in docnames:
        try:
            snap = api_get_status_snapshot(docname)
            if not snap.get("ok"):
                continue
            lanes = snap.get("lanes") or []
            for L in lanes:
                status = (L.get("lane_action_status") or "").strip().lower()
                if status == "requested":
                    lane_no = int(L.get("lane_no") or 0)
                    if lane_no == 1:
                        result.append((
                            docname,
                            lane_no,
                            (L.get("pcb_serial_no") or "").strip(),
                            (L.get("lane_action") or "step_sweep").strip()
                        ))
        except Exception:
            pass
    return result


# -----------------------------------------------------------------------------
# Action to CLI mode (18_FINAL_DOCTYPE_SPEC: internal codes)
# -----------------------------------------------------------------------------
ALLOWED_ACTIONS = ["step_sweep", "mode1", "mode2", "mode3", "mode0", "full_test"]


def action_to_cli_mode(action):
    """Map lane_action to CLI --mode value."""
    a = (action or "").strip().lower()
    return a if a in ALLOWED_ACTIONS else "step_sweep"


# -----------------------------------------------------------------------------
# Stdout parser: one JSON object per line (09_CLI_SPEC)
# -----------------------------------------------------------------------------

def parse_stdout_line(line):
    """Parse one line. Return event dict or None. Ignore non-JSON safely."""
    line = (line or "").strip()
    if not line:
        return None
    try:
        obj = json.loads(line)
        if isinstance(obj, dict) and obj.get("type"):
            return obj
    except (json.JSONDecodeError, ValueError):
        pass
    return None


# -----------------------------------------------------------------------------
# Accumulation (12_LIVE_UPDATE_FLOW)
# -----------------------------------------------------------------------------

def now_ts():
    return time.strftime("%Y-%m-%dT%H:%M:%S", time.gmtime(time.time()))


# -----------------------------------------------------------------------------
# Lane worker: claim, launch subprocess, handle events
# -----------------------------------------------------------------------------

def run_lane_worker(docname, lane_no, pcb_serial_no, lane_action):
    """
    Claim lane, launch AUTO_PTS3v16.py --cli, read stdout, push events to ERP.
    If subprocess launch fails after claim, call mark_lane_failed immediately.
    """
    if not pcb_serial_no:
        api_mark_lane_failed(docname, lane_no, "", "Missing PCB Serial No")
        return

    cli_mode = action_to_cli_mode(lane_action)

    # 1. Claim lane (sets Queued, returns run_id)
    claim_resp = api_claim_lane(docname, lane_no)
    if not claim_resp.get("ok"):
        print("[PTS3] Claim failed %s lane %s: %s" % (docname, lane_no, claim_resp.get("reason", "unknown")))
        return

    run_id = claim_resp.get("run_id") or ""
    print("[PTS3] Claimed %s lane %s run_id=%s launching %s" % (docname, lane_no, run_id[:20] + "..." if len(run_id) > 20 else run_id, cli_mode))

    try:
        api_append_lane_log(docname, lane_no, run_id,
            "[ERP] Job received: %s lane %s action=%s serial=%s\n" % (docname, lane_no, lane_action or "", pcb_serial_no or ""))
    except Exception:
        pass

    # 2. Preferred: persistent local runner (keeps scope init once).
    # Fallback: spawn AUTO_PTS3v17.py per action.
    runner_stream = None
    try:
        runner_stream = open_runner_stream(cli_mode, pcb_serial_no, lane_no, run_id)
        print("[PTS3] Using runner %s:%s (scope session kept hot)" % (PTS3_RUNNER_HOST, PTS3_RUNNER_PORT))
    except Exception as e:
        runner_stream = None
        print("[PTS3] Runner not available, falling back to subprocess (cold init each job): %s" % e)

    p = None
    if runner_stream is None:
        # -u = unbuffered stdout so sweep_point events arrive in real time
        cmd = [
            PYTHON_PATH,
            "-u",
            PTS3_SCRIPT,
            "--cli",
            "--mode", cli_mode,
            "--serial", pcb_serial_no,
            "--lane_no", str(lane_no),
            "--run_id", run_id
        ]

        try:
            p = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                cwd=BASE_DIR
            )
        except Exception as e:
            api_mark_lane_failed(docname, lane_no, run_id, "Subprocess launch failed: " + str(e))
            return

    # 3. Subprocess started: set Running
    try:
        api_update_lane_fields(docname, lane_no, run_id, {
            "lane_action_status": "Running",
            "live_progress_message": "Started",
            "last_heartbeat_at": now_ts(),
            "last_live_update_at": now_ts()
        })
    except Exception:
        pass

    # Accumulators
    freqs, left_vals, right_vals, diff_vals = [], [], [], []
    live_table = {"left": {}, "right": {}, "diff": {}}
    mode_values = {}
    last_abort_check = time.time()
    last_heartbeat_push = time.time()
    completed_received = [False]
    user_aborted = [False]
    failure_marked = [False]

    def push_fields(fields):
        try:
            api_update_lane_fields(docname, lane_no, run_id, fields)
        except Exception as ex:
            print("[PTS3] update_lane_fields error: %s" % ex)

    def handle_event(ev):
        ev_type = ev.get("type") or ""
        ts = ev.get("ts") or now_ts()

        if ev_type == "status":
            msg = ev.get("msg", "")
            fields = {"live_status": msg, "live_progress_message": msg, "last_live_update_at": ts}
            if ev.get("freq") is not None:
                fields["live_current_freq"] = ev.get("freq")
            push_fields(fields)
        elif ev_type == "sweep_point":
            freq = ev.get("freq")
            left = ev.get("left")
            right = ev.get("right")
            diff = ev.get("diff")
            if freq is not None:
                freqs.append(freq)
                left_vals.append(left)
                right_vals.append(right)
                diff_vals.append(diff)
                key = str(freq) + "hz"
                live_table["left"][key] = left
                live_table["right"][key] = right
                live_table["diff"][key] = diff
            graph = {"type": "sweep", "freqs": list(freqs), "left": list(left_vals),
                     "right": list(right_vals), "diff": list(diff_vals)}
            push_fields({
                "live_graph_json": json.dumps(graph),
                "live_table_json": json.dumps(live_table),
                "live_current_freq": freq,
                "last_live_update_at": ts
            })
        elif ev_type == "mode_progress":
            push_fields({
                "live_current_mode": ev.get("mode", ""),
                "live_progress_message": ev.get("msg", ev.get("mode", "")),
                "last_live_update_at": ts
            })
        elif ev_type == "mode_point":
            mode_key = "Mode" + str(ev.get("mode", ""))
            p1, p2, d = ev.get("p1"), ev.get("p2"), ev.get("diff")
            if mode_key and p1 is not None:
                mode_values[mode_key] = {"p1": p1, "p2": p2 or 0, "diff": d or 0}
                tbl = dict(live_table)
                tbl[mode_key] = {"p1": p1, "p2": p2 or 0, "diff": d or 0}
                push_fields({"live_table_json": json.dumps(tbl), "last_live_update_at": ts})
        elif ev_type == "mode_complete":
            mode_key = "Mode" + str(ev.get("mode", ""))
            p1, p2, d = ev.get("p1"), ev.get("p2"), ev.get("diff")
            if mode_key:
                mode_values[mode_key] = {"p1": p1 or 0, "p2": p2 or 0, "diff": d or 0}
                tbl = dict(live_table)
                tbl[mode_key] = {"p1": p1 or 0, "p2": p2 or 0, "diff": d or 0}
                push_fields({
                    "live_table_json": json.dumps(tbl),
                    "live_current_mode": mode_key,
                    "live_progress_message": mode_key + " complete",
                    "last_live_update_at": ts
                })
        elif ev_type == "completed":
            result = ev.get("result") or {}
            result.setdefault("run_id", run_id)
            result.setdefault("serial", pcb_serial_no)
            result.setdefault("operation", cli_mode)
            if not result.get("datetime"):
                result["datetime"] = now_ts()
            if not result.get("left_right_diff_summary") and not result.get("table"):
                result["left_right_diff_summary"] = live_table
            # Merge live mode points if worker omitted mode_values in completed payload
            mv_acc = result.get("mode_values") or {}
            if (not isinstance(mv_acc, dict) or len(mv_acc) == 0) and mode_values:
                result["mode_values"] = dict(mode_values)
            # Rebuild mode graph when mode_values exist but graph is empty (common CLI/daemon gap)
            g = result.get("graph") or {}
            if isinstance(g, dict) and len(g) == 0 and result.get("mode_values"):
                mv = result.get("mode_values") or {}
                if isinstance(mv, dict) and len(mv) == 1:
                    mk = list(mv.keys())[0]
                    result["graph"] = {"type": "mode", mk: mv[mk]}
            if not result.get("graph") and freqs and (cli_mode == "step_sweep" or cli_mode == "submit"):
                result["graph"] = {"type": "sweep", "freqs": list(freqs), "left": list(left_vals),
                                  "right": list(right_vals), "diff": list(diff_vals)}
            # Enrich artifact_paths with pc_name for station identity
            ap = result.get("artifact_paths")
            if isinstance(ap, dict):
                if "pc_name" not in ap or not ap.get("pc_name"):
                    result["artifact_paths"] = dict(ap)
                    result["artifact_paths"]["pc_name"] = CONNECTOR_NAME
            else:
                path_str = (ap or "").strip() if isinstance(ap, str) else ""
                result["artifact_paths"] = {
                    "pc_name": CONNECTOR_NAME,
                    "excel_path": path_str,
                    "log_path": "",
                    "plot_path": ""
                }
            try:
                api_save_final_result(docname, lane_no, run_id, result)
                completed_received[0] = True
            except Exception as ex:
                if not failure_marked[0]:
                    failure_marked[0] = True
                    api_mark_lane_failed(docname, lane_no, run_id, "save_final_result failed: " + str(ex))
        elif ev_type == "failed":
            if not failure_marked[0] and not completed_received[0]:
                failure_marked[0] = True
                api_mark_lane_failed(docname, lane_no, run_id, ev.get("error", "Unknown error"))
        elif ev_type == "log":
            try:
                api_append_lane_log(docname, lane_no, run_id, (ev.get("line", "") or "") + "\n")
            except Exception:
                pass

    # Read stdout line-by-line
    try:
        if runner_stream is not None:
            line_iter = runner_stream
        else:
            line_iter = iter(p.stdout.readline, "")

        for line in line_iter:
            if not line:
                break

            now = time.time()

            # Abort check (separate timer)
            if now - last_abort_check > ABORT_CHECK_SEC:
                last_abort_check = now
                if abort_requested(docname, lane_no):
                    user_aborted[0] = True
                    try:
                        if runner_stream is not None:
                            request_runner_abort(run_id, pcb_serial_no, lane_no)
                        else:
                            p.terminate()
                            p.wait(timeout=5)
                    except Exception:
                        try:
                            if p is not None:
                                p.kill()
                        except Exception:
                            pass
                    api_abort_lane(docname, lane_no)
                    return

            # Heartbeat (separate timer; actually sends last_heartbeat_at to ERP)
            if now - last_heartbeat_push >= HEARTBEAT_SEC:
                last_heartbeat_push = now
                push_fields({"last_heartbeat_at": now_ts()})

            ev = parse_stdout_line(line)
            if ev:
                handle_event(ev)
            else:
                try:
                    api_append_lane_log(docname, lane_no, run_id,
                                        line if line.endswith("\n") else line + "\n")
                except Exception:
                    pass

        rc = 0
        if p is not None:
            rc = p.wait()
    except Exception as ex:
        if not completed_received[0] and not user_aborted[0] and not failure_marked[0]:
            failure_marked[0] = True
            api_mark_lane_failed(docname, lane_no, run_id, "Connector error: " + str(ex))
        return

    if not user_aborted[0] and not completed_received[0] and not failure_marked[0] and rc != 0:
        failure_marked[0] = True
        api_mark_lane_failed(docname, lane_no, run_id,
                             "Subprocess exited with code %s" % rc)


# -----------------------------------------------------------------------------
# Poll loop
# -----------------------------------------------------------------------------

def poll_once():
    """Discover Requested lane 1 only, run one worker (v1 single-lane mode)."""
    jobs = discover_requested_lanes()
    if jobs:
        print("[PTS3] Found %s requested job(s)" % len(jobs))
    for docname, lane_no, pcb_serial_no, lane_action in jobs:
        run_lane_worker(docname, lane_no, pcb_serial_no, lane_action)
        break
    return len(jobs)


def poll_loop():
    """Main loop. Process one job per cycle to avoid overlap."""
    while True:
        try:
            poll_once()
        except Exception as e:
            print("[PTS3] Poll error: %s" % repr(e))
        time.sleep(POLL_SEC)


# -----------------------------------------------------------------------------
# Main
# -----------------------------------------------------------------------------

def main():
    print("[PTS3 Connector] PC=%s ERP=%s Script=%s" % (TARGET_PC, ERP_URL, PTS3_SCRIPT))
    print("[PTS3] Station field in PTS3 Test must exactly match: %s" % TARGET_PC)
    if not os.path.isfile(PTS3_SCRIPT):
        print("[PTS3] ERROR: Script not found: %s" % PTS3_SCRIPT)
        sys.exit(1)
    print("[PTS3] Preparing oscilloscope (runner init on %s:%s)…" % (PTS3_RUNNER_HOST, PTS3_RUNNER_PORT))
    prepare_scope_for_station()
    poll_loop()


if __name__ == "__main__":
    main()

