   ============================================================ */

(function () {
  function esc(s) {
    if (s == null) return "";
    const div = document.createElement("div");
    div.textContent = String(s);
    return div.innerHTML;
  }

  function pf_style($td, pf) {
    if (!pf) return;
    if (pf === "Pass") $td.css({ color: "#22c55e", fontWeight: "600" });
    if (pf === "Fail") $td.css({ color: "#ef4444", fontWeight: "600" });
  }

  var BOOK_CHART = {
    width: 820,
    height: 360,
    padding: { top: 18, right: 16, bottom: 36, left: 56 },
    fontSize: 10,
    lineLeft: "#E53935",
    lineRight: "#2196F3",
    lineDiff: "#4CAF50",
    barP1: "#E53935",
    barP2: "#2196F3",
    barDiff: "#4CAF50",
    axisColor: "var(--text-muted, #6c7680)",
    gridColor: "var(--border-color, #d1d8dd)",
  };

  function book_safe_json(val, fallback) {
    if (val == null || val === "") return fallback || {};
    if (typeof val === "object" && val !== null && !Array.isArray(val)) {
      return val;
    }
    if (typeof val === "string") {
      try {
        var o = JSON.parse(val);
        return o && typeof o === "object" && !Array.isArray(o) ? o : fallback || {};
      } catch (e) {
        return fallback || {};
      }
    }
    return fallback || {};
  }

  function book_format_num(v) {
    if (v == null || isNaN(v)) return "";
    var n = Number(v);
    return n % 1 === 0 ? String(n) : n.toFixed(2);
  }

  function book_build_sweep_from_lrd(t) {
    if (!t || typeof t !== "object") return null;
    var left = t.left || {};
    var right = t.right || {};
    var diff = t.diff || {};
    var keys = Object.keys(left).concat(Object.keys(right)).concat(Object.keys(diff));
    keys = keys.filter(function (k, i, a) {
      return a.indexOf(k) === i;
    }).sort(function (a, b) {
      var na = parseInt(String(a).replace(/[^0-9]/g, ""), 10) || 0;
      var nb = parseInt(String(b).replace(/[^0-9]/g, ""), 10) || 0;
      return na - nb;
    });
    if (keys.length < 2) return null;
    var freqs = [];
    var leftArr = [];
    var rightArr = [];
    var diffArr = [];
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      var hz = parseInt(String(k).replace(/[^0-9]/g, ""), 10);
      if (!isNaN(hz)) {
        freqs.push(hz);
        leftArr.push(left[k] != null ? left[k] : null);
        rightArr.push(right[k] != null ? right[k] : null);
        diffArr.push(diff[k] != null ? diff[k] : null);
      }
    }
    return freqs.length >= 2 ? { freqs: freqs, left: leftArr, right: rightArr, diff: diffArr } : null;
  }

  function book_render_sweep_svg(freqs, left, right, diff) {
    if (!freqs || freqs.length < 2) return "";
    var pw = BOOK_CHART.width;
    var ph = BOOK_CHART.height;
    var pad = BOOK_CHART.padding;
    var gx = pad.left;
    var gy = pad.top;
    var gw = pw - pad.left - pad.right;
    var gh = ph - pad.top - pad.bottom;
    var allVals = [];
    var i;
    for (i = 0; i < left.length; i++) {
      if (left[i] != null) allVals.push(Number(left[i]));
    }
    for (i = 0; i < right.length; i++) {
      if (right[i] != null) allVals.push(Number(right[i]));
    }
    for (i = 0; i < diff.length; i++) {
      if (diff[i] != null) allVals.push(Number(diff[i]));
    }
    var vMin = allVals.length ? Math.min.apply(null, allVals) : 0;
    var vMax = allVals.length ? Math.max.apply(null, allVals) : 1;
    var vRange = vMax - vMin || 1;
    var freqMin = Number(freqs[0]) || 0;
    var freqMax = Number(freqs[freqs.length - 1]) || 1;
    var freqRange = freqMax - freqMin || 1;
    function xFromFreq(f) {
      return gx + ((Number(f) - freqMin) / freqRange) * gw;
    }
    function y(v) {
      return gy + gh - ((Number(v) - vMin) / vRange) * gh;
    }
    function path(arr) {
      var pts = [];
      for (var j = 0; j < arr.length; j++) {
        if (arr[j] != null && !isNaN(Number(arr[j]))) {
          var f = Number(freqs[j]);
          pts.push(xFromFreq(f) + "," + y(arr[j]));
        }
      }
      return pts.length ? "M" + pts.join(" L") : "";
    }
    var fs = BOOK_CHART.fontSize;
    var axisClr = BOOK_CHART.axisColor;
    var gridClr = BOOK_CHART.gridColor;
    var svg =
      '<svg width="' +
      pw +
      '" height="' +
      ph +
      '" viewBox="0 0 ' +
      pw +
      " " +
      ph +
      '" style="max-width:100%;height:auto;display:block;"><g>';
    var tick;
    for (tick = freqMin; tick <= freqMax; tick += 2) {
      var xx = xFromFreq(tick);
      if (xx >= gx - 1 && xx <= gx + gw + 1) {
        svg +=
          '<line x1="' +
          xx +
          '" y1="' +
          (gy + gh) +
          '" x2="' +
          xx +
          '" y2="' +
          gy +
          '" stroke="' +
          gridClr +
          '" stroke-width="0.5" opacity="0.5"/>';
        svg +=
          '<text x="' +
          xx +
          '" y="' +
          (ph - 4) +
          '" text-anchor="middle" font-size="' +
          fs +
          '" fill="' +
          axisClr +
          '">' +
          tick +
          "</text>";
      }
    }
    var yticks = 5;
    for (var yi = 0; yi <= yticks; yi++) {
      var yy = gy + gh - (yi / yticks) * gh;
      var v = vMin + (yi / yticks) * vRange;
      svg +=
        '<line x1="' +
        gx +
        '" y1="' +
        yy +
        '" x2="' +
        (gx + gw) +
        '" y2="' +
        yy +
        '" stroke="' +
        gridClr +
        '" stroke-width="0.5" opacity="0.5"/>';
      svg +=
        '<text x="' +
        (gx - 6) +
        '" y="' +
        (yy + 3) +
        '" text-anchor="end" font-size="' +
        fs +
        '" fill="' +
        axisClr +
        '">' +
        book_format_num(v) +
        "</text>";
    }
    svg +=
      '<line x1="' +
      gx +
      '" y1="' +
      (gy + gh) +
      '" x2="' +
      (gx + gw) +
      '" y2="' +
      (gy + gh) +
      '" stroke="' +
      axisClr +
      '" stroke-width="1"/>';
    svg +=
      '<line x1="' +
      gx +
      '" y1="' +
      gy +
      '" x2="' +
      gx +
      '" y2="' +
      (gy + gh) +
      '" stroke="' +
      axisClr +
      '" stroke-width="1"/>';
    var pL = path(left);
    var pR = path(right);
    var pD = path(diff);
    if (pL) svg += '<path d="' + pL + '" fill="none" stroke="' + BOOK_CHART.lineLeft + '" stroke-width="2"/>';
    if (pR) svg += '<path d="' + pR + '" fill="none" stroke="' + BOOK_CHART.lineRight + '" stroke-width="2"/>';
    if (pD) svg += '<path d="' + pD + '" fill="none" stroke="' + BOOK_CHART.lineDiff + '" stroke-width="1.5" stroke-dasharray="4,2"/>';
    svg += "</g></svg>";
    return svg;
  }

  function book_render_lr_svg(freqs, left, right) {
    var empty = [];
    for (var i = 0; i < (freqs || []).length; i++) empty.push(null);
    return book_render_sweep_svg(freqs, left || empty, right || empty, empty);
  }

  function book_render_diff_svg(freqs, diff) {
    var empty = [];
    for (var i = 0; i < (freqs || []).length; i++) empty.push(null);
    return book_render_sweep_svg(freqs, empty, empty, diff || empty);
  }

  function book_get_mode_val(m, key) {
    if (m[key]) return m[key];
    var lower = key.toLowerCase();
    if (m[lower]) return m[lower];
    return null;
  }

  function book_render_mode_svg(modeData) {
    var order = ["Mode1", "Mode2", "Mode3", "Mode0"];
    var rows = [];
    for (var i = 0; i < order.length; i++) {
      var v = book_get_mode_val(modeData, order[i]);
      if (v && typeof v === "object") {
        rows.push({
          label: order[i],
          p1: v.p1 != null ? Number(v.p1) : 0,
          p2: v.p2 != null ? Number(v.p2) : 0,
          diff: v.diff != null ? Number(v.diff) : 0,
        });
      }
    }
    if (!rows.length) return "";
    var pw = BOOK_CHART.width;
    var ph = 200;
    var pad = { top: 20, right: 16, bottom: 36, left: 48 };
    var gw = pw - pad.left - pad.right;
    var gh = ph - pad.top - pad.bottom;
    var maxVal = 0;
    var r;
    for (r = 0; r < rows.length; r++) {
      if (rows[r].p1 > maxVal) maxVal = rows[r].p1;
      if (rows[r].p2 > maxVal) maxVal = rows[r].p2;
      if (Math.abs(rows[r].diff) > maxVal) maxVal = Math.abs(rows[r].diff);
    }
    maxVal = maxVal || 1;
    var minVal = 0;
    var valRange = maxVal - minVal || 1;
    var groupW = gw / Math.max(rows.length, 1);
    var barW = groupW / 5;
    var gap = barW * 0.3;
    var totalBars = 3 * barW + 2 * gap;
    function barX(idx, offset) {
      var groupCenter = pad.left + (idx + 0.5) * groupW;
      var startX = groupCenter - totalBars / 2;
      return startX + offset * (barW + gap);
    }
    function barH(v) {
      var val = Number(v) || 0;
      return Math.max(0, ((val - minVal) / valRange) * gh);
    }
    var axisClr = BOOK_CHART.axisColor;
    var gridClr = BOOK_CHART.gridColor;
    var fs = BOOK_CHART.fontSize;
    var fsSmall = Math.max(6, fs - 2);
    var svg =
      '<svg viewBox="0 0 ' +
      pw +
      " " +
      ph +
      '" style="max-width:100%;height:auto;display:block;"><g>';
    for (var yi = 0; yi <= 4; yi++) {
      var yy = pad.top + gh - (yi / 4) * gh;
      var yVal = minVal + (yi / 4) * valRange;
      svg +=
        '<line x1="' +
        pad.left +
        '" y1="' +
        yy +
        '" x2="' +
        (pw - pad.right) +
        '" y2="' +
        yy +
        '" stroke="' +
        gridClr +
        '" stroke-width="0.5" opacity="0.5"/>';
      svg +=
        '<text x="' +
        (pad.left - 6) +
        '" y="' +
        (yy + 3) +
        '" text-anchor="end" font-size="' +
        fs +
        '" fill="' +
        axisClr +
        '">' +
        book_format_num(yVal) +
        "</text>";
    }
    svg +=
      '<line x1="' +
      pad.left +
      '" y1="' +
      (pad.top + gh) +
      '" x2="' +
      (pw - pad.right) +
      '" y2="' +
      (pad.top + gh) +
      '" stroke="' +
      axisClr +
      '" stroke-width="1"/>';
    var baseY = pad.top + gh;
    for (var bi = 0; bi < rows.length; bi++) {
      var x0 = barX(bi, 0);
      var x1 = barX(bi, 1);
      var x2 = barX(bi, 2);
      var h1 = barH(rows[bi].p1);
      var h2 = barH(rows[bi].p2);
      var hd = barH(Math.abs(rows[bi].diff));
      svg +=
        '<rect x="' +
        x0 +
        '" y="' +
        (baseY - h1) +
        '" width="' +
        barW +
        '" height="' +
        h1 +
        '" fill="' +
        BOOK_CHART.barP1 +
        '"/>';
      svg +=
        '<rect x="' +
        x1 +
        '" y="' +
        (baseY - h2) +
        '" width="' +
        barW +
        '" height="' +
        h2 +
        '" fill="' +
        BOOK_CHART.barP2 +
        '"/>';
      svg +=
        '<rect x="' +
        x2 +
        '" y="' +
        (baseY - hd) +
        '" width="' +
        barW +
        '" height="' +
        hd +
        '" fill="' +
        BOOK_CHART.barDiff +
        '"/>';
      if (rows[bi].p1 > 0) {
        svg +=
          '<text x="' +
          (x0 + barW / 2) +
          '" y="' +
          (baseY - h1 - 3) +
          '" text-anchor="middle" font-size="' +
          fsSmall +
          '" fill="' +
          axisClr +
          '">' +
          book_format_num(rows[bi].p1) +
          "</text>";
      }
      if (rows[bi].p2 > 0) {
        svg +=
          '<text x="' +
          (x1 + barW / 2) +
          '" y="' +
          (baseY - h2 - 3) +
          '" text-anchor="middle" font-size="' +
          fsSmall +
          '" fill="' +
          axisClr +
          '">' +
          book_format_num(rows[bi].p2) +
          "</text>";
      }
      svg +=
        '<text x="' +
        (pad.left + bi * groupW + groupW / 2) +
        '" y="' +
        (ph - 8) +
        '" text-anchor="middle" font-size="' +
        fs +
        '" fill="' +
        axisClr +
        '">' +
        esc(rows[bi].label) +
        "</text>";
    }
    svg += "</g></svg>";
    return svg;
  }

  function book_render_sweep_html(payload) {
    var g = book_safe_json(payload.final_graph_json, null);
    var isSweep =
      g && (g.type === "sweep" || g.type === "step_sweep") && (g.freqs || []).length >= 2;
    if (!isSweep) {
      var lrd = book_safe_json(payload.left_right_diff_summary_json, null);
      g = book_build_sweep_from_lrd(lrd);
    }
    if (!g || !g.freqs || g.freqs.length < 2) {
      return '<p class="text-muted">' + esc(__("No step sweep data for this run")) + "</p>";
    }
    var freqs = g.freqs || [];
    var left = g.left || [];
    var right = g.right || [];
    var diff = g.diff || [];
    var legLR =
      '<p style="font-size:11px;margin:0 0 6px 0;color:var(--text-color,#36414c);">' +
      '<span style="color:' +
      BOOK_CHART.lineLeft +
      '">—</span> Left &nbsp; ' +
      '<span style="color:' +
      BOOK_CHART.lineRight +
      '">—</span> Right' +
      "</p>";
    var legD =
      '<p style="font-size:11px;margin:0 0 6px 0;color:var(--text-color,#36414c);">' +
      '<span style="color:' +
      BOOK_CHART.lineDiff +
      '">- -</span> Diff' +
      "</p>";
    return (
      '<div style="display:flex;flex-direction:column;gap:10px;">' +
      '<div>' +
      '<div style="font-weight:600;margin:0 0 4px 0;">' + esc(__("Left / Right vs Hz")) + "</div>" +
      legLR +
      '<div class="pts3-book-sweep-svg-wrap">' +
      book_render_lr_svg(freqs, left, right) +
      "</div></div>" +
      '<div>' +
      '<div style="font-weight:600;margin:0 0 4px 0;">' + esc(__("Diff vs Hz")) + "</div>" +
      legD +
      '<div class="pts3-book-sweep-svg-wrap">' +
      book_render_diff_svg(freqs, diff) +
      "</div></div>" +
      "</div>"
    );
  }

  function book_render_mode_html(payload) {
    var m = book_safe_json(payload.mode_values_json, null);
    if (!m || typeof m !== "object" || !Object.keys(m).length) {
      return '<p class="text-muted">' + esc(__("No mode data for this run")) + "</p>";
    }
    var leg =
      '<p style="font-size:11px;margin:0 6px 6px 0;color:var(--text-color,#36414c);">' +
      '<span style="color:' +
      BOOK_CHART.barP1 +
      '">■</span> P1 &nbsp; ' +
      '<span style="color:' +
      BOOK_CHART.barP2 +
      '">■</span> P2 &nbsp; ' +
      '<span style="color:' +
      BOOK_CHART.barDiff +
      '">■</span> Diff' +
      "</p>";
    var svg = book_render_mode_svg(m);
    if (!svg) {
      return '<p class="text-muted">' + esc(__("No mode data for this run")) + "</p>";
    }
    return leg + svg;
  }

