    bind() {
      const me = this;

      this.$root.find(".pts3-book-serial-refresh").on("click", function () {
        me.loadSerialList(true);
      });
      this.$serialLoadMoreBtn.on("click", function () {
        me.loadSerialList(false);
      });
      this.$serialFilter.on("input", function () {
        if (me.serialFilterDebounce) clearTimeout(me.serialFilterDebounce);
        me.serialFilterDebounce = setTimeout(function () {
          me.loadSerialList(true);
        }, 400);
      });

      this.$btn_search.on("click", function () {
        me.search();
      });

      this.$serial.on("keydown", function (e) {
        if (e && e.key === "Enter") {
          e.preventDefault();
          me.search();
        }
      });

      this.$btn_open_latest.on("click", function () {
        if (me.latest_name) {
          frappe.set_route("Form", "PTS3 Result", me.latest_name);
        }
      });

      this.$root.find(".pts3-book-runid-load").on("click", function () {
        me.loadGraphsByRunId();
      });
      this.$root.find(".pts3-book-btn-latest-sweep").on("click", function () {
        const n = me.findLatestSweepResultName();
        if (n) {
          me.$selectSweep.val(n);
          me.loadSweepChartForResult(n);
        } else {
          frappe.msgprint(__("No step_sweep run in this list"));
        }
      });
      this.$root.find(".pts3-book-btn-latest-mode").on("click", function () {
        const n = me.findLatestModeResultName();
        if (n) {
          me.$selectMode.val(n);
          me.loadModeChartForResult(n);
        } else {
          frappe.msgprint(__("No mode run in this list"));
        }
      });
      this.$selectSweep.on("change", function () {
        const v = $(this).val();
        if (v) me.loadSweepChartForResult(v);
      });
      this.$selectMode.on("change", function () {
        const v = $(this).val();
        if (v) me.loadModeChartForResult(v);
      });
    }

    restore_from_route() {
      // Optional: allow route like #pts3-book?pcb=XYZ
      try {
        const r = frappe.get_route();
        // r: ["pts3-book", "something"] typically; query string is separate
        const q = frappe.utils.get_query_params();
        if (q && q.pcb) {
          const pcb = String(q.pcb || "").trim();
          if (pcb) {
            this.$serial.val(pcb);
            this.search();
          }
        }
      } catch (e) {}
    }

    loadSerialList(reset) {
      const me = this;
      if (reset) {
        this.serialListOffset = 0;
        this.$serialTableWrap.html(
          '<p class="text-muted" style="margin:8px 0;">' + esc(__("Loading…")) + "</p>"
        );
      }
      if (this.loadingSerials) return;
      this.loadingSerials = true;

      const search = String(this.$serialFilter.val() || "").trim();

      frappe.call({
        method: "pts3_api",
        args: {
          api_cmd: "pts3_book_list_serials",
          search: search,
          limit: this.serialListLimit,
          offset: this.serialListOffset,
        },
        callback: function (r) {
          me.loadingSerials = false;
          if (!r || !r.message || !r.message.ok) {
            me.$serialTableWrap.html(
              '<p class="text-danger">' + esc(__("Could not load serial list")) + "</p>"
            );
            return;
          }
          me.renderSerialTable(r.message, reset);
        },
        error: function () {
          me.loadingSerials = false;
          me.$serialTableWrap.html(
            '<p class="text-danger">' + esc(__("Could not load serial list")) + "</p>"
          );
        },
      });
    }

    renderSerialTable(data, reset) {
      const rows = data.serials || [];
      const distinct = data.distinct_count != null ? data.distinct_count : 0;
      const me = this;

      if (reset) {
        this.$serialTableWrap.empty();
        if (!rows.length) {
          this.$serialTableWrap.html(
            '<p class="text-muted">' + esc(__("No PTS3 Result rows yet (no serials).")) + "</p>"
          );
          this.$serialLoadMoreWrap.hide();
          this.serialListOffset = 0;
          return;
        }
        this.$serialTableWrap.append(
          '<p class="text-muted" style="font-size:12px;margin-bottom:6px;">' +
            esc(__("Distinct serials")) +
            ": " +
            distinct +
            "</p>"
        );
        this.$serialTableWrap.append(
          '<table class="table table-bordered table-condensed">' +
            "<thead><tr>" +
            "<th>" + esc(__("PCB Serial No")) + "</th>" +
            "<th>" + esc(__("Runs")) + "</th>" +
            '<th style="width:140px;">' + esc(__("Open book")) + "</th>" +
            '</tr></thead><tbody class="pts3-book-serial-tbody"></tbody></table>'
        );
      }

      const $tb = this.$serialTableWrap.find("tbody.pts3-book-serial-tbody");
      if (!$tb.length) {
        return;
      }

      rows.forEach(function (row) {
        const sn = row.pcb_serial_no || "";
        const rc = row.run_count != null ? row.run_count : "-";
        const $tr = $("<tr></tr>");
        $tr.append($("<td></td>").text(sn));
        $tr.append($("<td></td>").text(String(rc)));
        const $btn = $('<button type="button" class="btn btn-xs btn-primary"></button>')
          .text(__("Select"))
          .on("click", function () {
            me.$serial.val(sn);
            me.search();
            try {
              me.$serial[0].scrollIntoView({ behavior: "smooth", block: "center" });
            } catch (e) {}
          });
        $tr.append($("<td></td>").append($btn));
        $tb.append($tr);
      });

      this.serialListOffset = (data.offset != null ? data.offset : 0) + rows.length;

      const hasMore =
        typeof data.has_more === "boolean"
          ? data.has_more
          : rows.length >= this.serialListLimit;
      if (hasMore) {
        this.$serialLoadMoreWrap.show();
        this.$serialLoadMoreBtn.prop("disabled", false).text(__("Load more serials"));
      } else {
        this.$serialLoadMoreWrap.hide();
      }
    }

    search() {
      const pcb = String(this.$serial.val() || "").trim();
      if (!pcb) {
        frappe.msgprint(__("Enter PCB Serial No"));
        return;
      }

      this.pcb_serial_no = pcb;
      this.offset = 0;
      this.latest_name = "";
      this.$btn_open_latest.prop("disabled", true);
      this.$header.hide();
      this.$graphs.hide();
      this.bookRuns = [];
      this.$graphSweep.empty();
      this.$graphMode.empty();
      this.$selectSweep.empty();
      this.$selectMode.empty();
      this.$runIdInput.val("");

      // Reset table state
      this.$table = null;
      this.$tbody = null;
      if (this.$more_wrap) this.$more_wrap.remove();
      this.$more_wrap = null;
      this.$more_btn = null;

      this.$runs.html(
        '<p class="text-muted" style="margin-top:0.75rem;">' +
          esc(__("Loading...")) +
        "</p>"
      );

      this.$graphs.show();
      this.$graphSweep.html(
        '<p class="text-muted" style="margin:8px;">' + esc(__("Loading graph data from PTS3 Result…")) + "</p>"
      );
      this.$graphMode.html(
        '<p class="text-muted" style="margin:8px;">' + esc(__("Loading graph data from PTS3 Result…")) + "</p>"
      );

      this.fetch_data();
    }

    fetch_data() {
      const me = this;
      if (this.loading) return;
      this.loading = true;

      frappe.call({
        method: "pts3_api",
        args: {
          api_cmd: "pts3_book_get",
          pcb_serial_no: this.pcb_serial_no,
          limit: this.limit,
          offset: this.offset,
        },
        callback: function (r) {
          me.loading = false;
          if (!r || !r.message) {
            me.$runs.html('<p class="text-danger">' + esc(__("No response")) + "</p>");
            return;
          }
          const data = r.message;
          if (!data.ok) {
            const reason = data.reason || __("Request failed");
            me.$runs.html('<p class="text-danger">' + esc(reason) + "</p>");
            return;
          }

          me.render_header(data);
          me.render_runs(data);
        },
        error: function () {
          me.loading = false;
          me.$runs.html('<p class="text-danger">' + esc(__("Request failed")) + "</p>");
        },
      });
    }

    render_header(data) {
      const latest = data.latest_run || null;

      this.$serial_val.text(data.pcb_serial_no || this.pcb_serial_no || "");
      this.$run_count.text(String(data.run_count != null ? data.run_count : 0));

      if (latest && latest.name) {
        this.latest_name = latest.name;
        this.$btn_open_latest.prop("disabled", false);

        const dt = latest.datetime
          ? frappe.datetime.str_to_user(latest.datetime)
          : "-";
        const op = latest.operation || "-";
        const pf = latest.pass_fail || "-";
        const dom = latest.dominant_channel || "-";
        const mx = (latest.max_value !== undefined && latest.max_value !== null) ? latest.max_value : "-";
        const run_id = latest.run_id || "-";
        const lane = latest.lane_no != null && latest.lane_no !== "" ? latest.lane_no : "-";
        const testRef = latest.pts3_test_ref || "-";

        this.$latest_summary.text(
          dt + " | " + op + " | " + pf + " | " + dom + " | " + mx + " | L" + lane + " | " + testRef + " | " + run_id
        );
      } else {
        this.latest_name = "";
        this.$btn_open_latest.prop("disabled", true);
        this.$latest_summary.text("-");
      }

      this.$header.show();
    }

    render_runs(data) {
      const me = this;
      const runs = data.runs || [];

      if (!runs.length && this.offset === 0) {
        this.$runs.html(
          '<p class="text-muted" style="margin-top:0.75rem;">' +
            esc(__("No runs found for this PCB Serial No")) +
          "</p>"
        );
        this.$table = null;
        this.$tbody = null;
        this.$graphs.hide();
        this.bookRuns = [];
        return;
      }

      // Create table once
      if (!this.$table) {
        this.$table = $(
          '<table class="table table-bordered table-condensed">' +
            "<thead><tr>" +
              "<th>" + esc(__("Datetime")) + "</th>" +
              "<th>" + esc(__("Operation")) + "</th>" +
              "<th>" + esc(__("Pass/Fail")) + "</th>" +
              "<th>" + esc(__("Dominant")) + "</th>" +
              "<th>" + esc(__("Max")) + "</th>" +
              "<th>" + esc(__("Lane")) + "</th>" +
              "<th>" + esc(__("PTS3 Test")) + "</th>" +
              "<th>" + esc(__("Run ID")) + "</th>" +
              '<th style="width:120px;">' + esc(__("Open")) + "</th>" +
            "</tr></thead>" +
            "<tbody></tbody>" +
          "</table>"
        );
        this.$tbody = this.$table.find("tbody");
        this.$runs.empty().append(this.$table);
      }

      // Clear rows on first page
      if (this.offset === 0) {
        this.$tbody.empty();
      }

      // Append rows (newest-first comes from backend; do NOT sort here)
      runs.forEach(function (run) {
        const dt = run.datetime
          ? frappe.datetime.str_to_user(run.datetime)
          : "";

        const $tr = $("<tr></tr>");

        $tr.append($("<td></td>").text(dt || "-"));
        $tr.append($("<td></td>").text(run.operation || "-"));

        const pf = run.pass_fail || "-";
        const $pf = $("<td></td>").text(pf);
        pf_style($pf, pf);
        $tr.append($pf);

        $tr.append($("<td></td>").text(run.dominant_channel || "-"));
        $tr.append(
          $("<td></td>").text(
            (run.max_value !== undefined && run.max_value !== null) ? run.max_value : "-"
          )
        );
        $tr.append(
          $("<td></td>").text(
            (run.lane_no != null && run.lane_no !== "") ? String(run.lane_no) : "-"
          )
        );
        const testRef = run.pts3_test_ref || "";
        const $testTd = $("<td></td>");
        if (testRef) {
          const $a = $('<a href="#"></a>').text(testRef);
          $a.on("click", function (e) {
            e.preventDefault();
            frappe.set_route("Form", "PTS3 Test", testRef);
          });
          $testTd.append($a);
        } else {
          $testTd.text("-");
        }
        $tr.append($testTd);
        $tr.append($("<td></td>").text(run.run_id || "-"));

        const $btn = $('<button class="btn btn-xs btn-default"></button>')
          .text(__("Open Result"))
          .on("click", function () {
            if (run.name) {
              // Show charts in the PTS3 Book first (stays on this page).
              me.loadChartsForResult(run.name);

              // Then open the full PTS3 Result form in a new tab.
              // (Keeps the book graphs visible for fast inspection.)
              try {
                var url = "#Form/PTS3%20Result/" + encodeURIComponent(run.name);
                window.open(url, "_blank");
              } catch (e) {}
            }
          });

        $tr.append($("<td></td>").append($btn));
        me.$tbody.append($tr);
      });

      // Setup / update "Load more"
      if (!this.$more_wrap) {
        this.$more_wrap = $('<div class="text-center" style="margin-top:0.75rem;"></div>');
        this.$more_btn = $('<button class="btn btn-sm btn-default"></button>').appendTo(this.$more_wrap);

        this.$more_btn.on("click", function () {
          me.offset += me.limit;
          me.fetch_data();
        });

        this.$runs.append(this.$more_wrap);
      }

      const has_more = (typeof data.has_more === "boolean")
        ? data.has_more
        : (runs.length >= this.limit);

      if (has_more) {
        this.$more_wrap.show();
        this.$more_btn.prop("disabled", false).text(__("Load More"));
      } else {
        if (this.offset === 0) {
          this.$more_wrap.hide();
        } else {
          this.$more_wrap.show();
          this.$more_btn.prop("disabled", true).text(__("No more runs"));
        }
      }

      if (this.offset === 0 && runs.length) {
        this.setupGraphsFromRuns(data);
      }
    }

    findLatestSweepResultName() {
      const list = this.bookRuns || [];
      for (let i = 0; i < list.length; i++) {
        const op = (list[i].operation || "").toLowerCase();
        if (op === "step_sweep") return list[i].name;
      }
      return list.length ? list[0].name : null;
    }

    findLatestModeResultName() {
      const list = this.bookRuns || [];
      for (let i = 0; i < list.length; i++) {
        const op = list[i].operation || "";
        if (/^mode/i.test(op)) return list[i].name;
      }
      return list.length ? list[0].name : null;
    }

    populateGraphSelects() {
      const me = this;
      this.$selectSweep.empty();
      this.$selectMode.empty();
      (this.bookRuns || []).forEach(function (run) {
        const dt = run.datetime ? frappe.datetime.str_to_user(run.datetime) : "";
        const label =
          (dt || "-") + " | " + (run.operation || "-") + " | " + (run.run_id || "").substring(0, 48);
        me.$selectSweep.append($("<option></option>").attr("value", run.name).text(label));
        me.$selectMode.append($("<option></option>").attr("value", run.name).text(label));
      });
    }

    setupGraphsFromRuns(data) {
      const me = this;
      const runs = data.runs || [];
      if (!runs.length) {
        this.$graphs.hide();
        return;
      }
      const runCount = data.run_count != null ? data.run_count : runs.length;
      const needFullList = data.has_more === true || runCount > runs.length;

      function proceed(fullRuns) {
        me.bookRuns = fullRuns || runs;
        me.populateGraphSelects();
        me.$graphs.show();
        const sweepN = me.findLatestSweepResultName();
        const modeN = me.findLatestModeResultName();
        if (sweepN) {
          me.$selectSweep.val(sweepN);
          me.loadSweepChartForResult(sweepN);
        } else {
          me.$graphSweep.html('<p class="text-muted">' + esc(__("No step_sweep run in list")) + "</p>");
        }
        if (modeN) {
          me.$selectMode.val(modeN);
          me.loadModeChartForResult(modeN);
        } else {
          me.$graphMode.html('<p class="text-muted">' + esc(__("No mode run in list")) + "</p>");
        }
      }

      if (needFullList) {
        frappe.call({
          method: "pts3_api",
          args: {
            api_cmd: "pts3_book_get",
            pcb_serial_no: this.pcb_serial_no,
            limit: 500,
            offset: 0,
          },
          callback: function (r) {
            if (r && r.message && r.message.ok && r.message.runs && r.message.runs.length) {
              proceed(r.message.runs);
            } else {
              proceed(runs);
            }
          },
          error: function () {
            proceed(runs);
          },
        });
      } else {
        proceed(runs);
      }
    }

    fetchResultGraphs(args, callback) {
      frappe.call({
        method: "pts3_api",
        args: Object.assign({ api_cmd: "pts3_book_get_result_graphs" }, args),
        callback: function (r) {
          if (!r || !r.message) {
            frappe.msgprint(__("No response"));
            return;
          }
          if (!r.message.ok) {
            frappe.msgprint(__(r.message.reason || "Request failed"));
            return;
          }
          callback(r.message);
        },
        error: function () {
          frappe.msgprint(__("Request failed"));
        },
      });
    }

    loadSweepChartForResult(resultName) {
      const me = this;
      if (!resultName) return;
      this.$graphSweep.html('<p class="text-muted">' + esc(__("Loading…")) + "</p>");
      this.fetchResultGraphs({ result_name: resultName }, function (payload) {
        const sub =
          '<div style="font-size:12px;margin-bottom:8px;color:var(--text-muted,#8d99a6);">' +
          esc(payload.operation || "") +
          " · " +
          esc(payload.run_id || "") +
          "</div>";
        me.$graphSweep.html(sub + book_render_sweep_html(payload));
      });
    }

    loadModeChartForResult(resultName) {
      const me = this;
      if (!resultName) return;
      this.$graphMode.html('<p class="text-muted">' + esc(__("Loading…")) + "</p>");
      this.fetchResultGraphs({ result_name: resultName }, function (payload) {
        const sub =
          '<div style="font-size:12px;margin-bottom:8px;color:var(--text-muted,#8d99a6);">' +
          esc(payload.operation || "") +
          " · " +
          esc(payload.run_id || "") +
          "</div>";
        me.$graphMode.html(sub + book_render_mode_html(payload));
      });
    }

    loadChartsForResult(resultName) {
      const me = this;
      if (!resultName) return;

      // Make sure the graphs block is visible.
      this.$graphs.show();

      this.$graphSweep.html('<p class="text-muted">' + esc(__("Loading…")) + "</p>");
      this.$graphMode.html('<p class="text-muted">' + esc(__("Loading…")) + "</p>");

      this.fetchResultGraphs({ result_name: resultName }, function (payload) {
        const sub =
          '<div style="font-size:12px;margin-bottom:8px;color:var(--text-muted,#8d99a6);">' +
          esc(payload.operation || "") +
          " · " +
          esc(payload.run_id || "") +
          "</div>";
        me.$graphSweep.html(sub + book_render_sweep_html(payload));
        me.$graphMode.html(sub + book_render_mode_html(payload));
      });
    }

    loadGraphsByRunId() {
      const me = this;
      const rid = String(this.$runIdInput.val() || "").trim();
      if (!rid) {
        frappe.msgprint(__("Enter Run ID"));
        return;
      }
      const pcb = String(this.pcb_serial_no || "").trim();
      this.$graphSweep.html('<p class="text-muted">' + esc(__("Loading…")) + "</p>");
      this.$graphMode.html('<p class="text-muted">' + esc(__("Loading…")) + "</p>");
      this.fetchResultGraphs(
        { run_id: rid, pcb_serial_no: pcb },
        function (payload) {
          me.$selectSweep.val(payload.name);
          me.$selectMode.val(payload.name);
          me.$graphSweep.html(
            '<div style="font-size:12px;margin-bottom:8px;color:var(--text-muted,#8d99a6);">' +
              esc(payload.operation || "") +
              " · " +
              esc(payload.run_id || "") +
              "</div>" +
              book_render_sweep_html(payload)
          );
          me.$graphMode.html(
            '<div style="font-size:12px;margin-bottom:8px;color:var(--text-muted,#8d99a6);">' +
              esc(payload.operation || "") +
              " · " +
              esc(payload.run_id || "") +
              "</div>" +
              book_render_mode_html(payload)
          );
        }
      );
    }
  }

  frappe.pages["pts3-book"] = frappe.pages["pts3-book"] || {};
  frappe.pages["pts3-book"].on_page_load = function (wrapper) {
    wrapper.pts3_book = new PTS3BookPage(wrapper);
  };
})();
